import time, functools

def timed(fn):
    @functools.wraps(fn)
    def w(*a, **kw):
        t0 = time.perf_counter()
        try:
            return fn(*a, **kw)
        finally:
            dt = (time.perf_counter() - t0) * 1000
            print(f'[{fn.__name__}] {dt:.1f} ms')
    return w

